* **Περιστρέψτε τη γλάστρα** κάθε 2-3 εβδομάδες για ομοιόμορφη ανάπτυξη.
* **Πλησιάστε το παράθυρο:** η ένταση του φωτός πέφτει δραματικά με την απόσταση. Ένα μέτρο πιο κοντά κάνει μεγάλη διαφορά.
* **Μηδενική λίπανση τον χειμώνα** σε χαμηλό φως: το φυτό δεν αναπτύσσεται, τα άλατα συσσωρεύονται και καίνε τις ρίζες."
