## Σύντομη Απάντηση

Το καουτσουκόδεντρο (Ficus elastica) θέλει **φωτεινό χώρο χωρίς καυτό ήλιο, πότισμα μόνο όταν στεγνώσουν τα πάνω 3-5 εκατοστά του χώματος, και θερμοκρασία πάνω από 12-15 °C όλο τον χρόνο**. Το πιο συχνό πρόβλημα, να ρίχνει φύλλα, έχει σχεδόν πάντα μία από τέσσερις αιτίες: υπερβολικό πότισμα, ρεύμα ή κρύο, ξαφνική μετακίνηση, ή λίγο φως. Τα κάτω φύλλα που κιτρινίζουν και πέφτουν ένα ένα είναι φυσιολογικά σε ένα φυτό που μεγαλώνει ψηλά. Για να γίνει πιο θαμνώδες, το κλαδεύεις πάνω από έναν κόμπο (node) την άνοιξη, φορώντας γάντια, γιατί ο γαλακτώδης χυμός του ερεθίζει το δέρμα και είναι ελαφρά τοξικός για κατοικίδια.

## 1. Τι είναι αυτό το φυτό και τι να περιμένεις

Το καουτσουκόδεντρο, γνωστό και ως ελαστικός φίκος, κατάγεται από τα δάση της Ινδίας και της Νοτιοανατολικής Ασίας, όπου γίνεται μεγάλο δέντρο. Σε γλάστρα μέσα στο σπίτι φτάνει συνήθως τα **1,5-3 μέτρα** και μεγαλώνει περίπου 30-60 εκατοστά τον χρόνο όταν έχει καλές συνθήκες. Έχει μεγάλα, δερματώδη, γυαλιστερά φύλλα, και κάθε νέο φύλλο ξεπροβάλλει μέσα σε ένα **κόκκινο ή ροζ «φακελάκι»** (προφυλλικό κάλυμμα), που ξεραίνεται και πέφτει μόλις ανοίξει το φύλλο. Αυτό είναι φυσιολογικό και δεν χρειάζεται να το αφαιρέσεις.

Η μεγάλη του δύναμη είναι ότι **συγχωρεί**: ανέχεται ξηρό αέρα, λίγη καθυστέρηση στο πότισμα και μέτριο φως. Η μεγάλη του αδυναμία είναι ότι μισεί τις απότομες αλλαγές: μια μετακίνηση, ένα ρεύμα από το παράθυρο ή μια εβδομάδα με υπερβολικό πότισμα φτάνουν για να ρίξει φύλλα.

### Οι πρώτες δύο εβδομάδες στο σπίτι

Ένα καουτσουκόδεντρο που μόλις αγόρασες έρχεται από θερμοκήπιο με σταθερή υγρασία και έντονο, διάχυτο φως. Στο σπίτι θα ρίξει σχεδόν σίγουρα 2-4 φύλλα, και αυτό δεν σημαίνει ότι έκανες κάτι λάθος: προσαρμόζεται στο λιγότερο φως. Για να το περάσεις ομαλά:

1. Διάλεξε εξαρχής τη μόνιμη θέση, κοντά σε φωτεινό παράθυρο, μακριά από πόρτα εξώθυρας και κλιματιστικό.
2. Μην το μεταφυτεύσεις αμέσως. Άφησέ το στη γλάστρα του εργαστηρίου για 3-4 εβδομάδες και έλεγξε μόνο αν η γλάστρα έχει τρύπες.
3. Πότισε μόνο όταν στεγνώσει το πάνω μέρος του χώματος. Το φυτό που ταξίδεψε έχει ήδη πιει αρκετά.
4. Μετά από ένα μήνα, αν ανοίγουν νέα φύλλα, ξέρεις ότι η θέση είναι σωστή.

## 2. Φως: τι πραγματικά θέλει

| Θέση | Αποτέλεσμα |
| :--- | :--- |
| Κοντά σε ανατολικό ή δυτικό παράθυρο, χωρίς άμεσο μεσημεριανό ήλιο | Ιδανική: συμπαγής ανάπτυξη, σκούρα φύλλα |
| Νότιο παράθυρο, με διάφανη κουρτίνα | Πολύ καλή |
| Μέσα στο δωμάτιο, 1-2 μέτρα από το παράθυρο | Αποδεκτή, πιο αργή ανάπτυξη |
| Σκοτεινή γωνία | Τεντώνεται, ρίχνει κάτω φύλλα, γέρνει προς το φως |
| Άμεσος καλοκαιρινός ήλιος πίσω από τζάμι | Ζεματίζει τα φύλλα: καφέ, ξερές κηλίδες στην πλευρά του ήλιου |

Οι σκούρες πράσινες και μπορντό ποικιλίες (π.χ. Robusta, Burgundy) ανέχονται λιγότερο φως από τις **παρδαλές** (π.χ. Tineke, Ruby), που χρειάζονται περισσότερο για να κρατήσουν το σχέδιό τους και τείνουν να γίνονται πιο πράσινες σε σκιά. Γύρνα τη γλάστρα ένα τέταρτο κύκλου κάθε 2-3 εβδομάδες για ίση ανάπτυξη.

Στην Ελλάδα το καλοκαίρι μπορεί να μείνει έξω σε σκιερό ή ημισκιερό μπαλκόνι, αλλά **ποτέ σε άμεσο ήλιο**: τα φύλλα του καίγονται εύκολα. Μπαίνει μέσα όταν οι νύχτες πέσουν κάτω από 12-15 °C.

## 3. Πότισμα: το κλειδί

Η πιο ασφαλής μέθοδος είναι ο έλεγχος με το δάχτυλο: **βάλε το δάχτυλο 3-5 εκατοστά στο χώμα και πότισε μόνο αν είναι στεγνό**. Μετά πότισε αρκετά ώστε να τρέξει νερό από τον πάτο και άδειασε το πιατάκι μέσα σε 15-30 λεπτά.

| Εποχή | Συχνότητα (ενδεικτικά, γλάστρα 25-30 cm) |
| :--- | :--- |
| Άνοιξη-Καλοκαίρι | κάθε 7-10 ημέρες, σε ζέστη λίγο πιο συχνά |
| Φθινόπωρο | κάθε 10-14 ημέρες |
| Χειμώνας (θερμαινόμενο σπίτι) | κάθε 14-21 ημέρες |

Το νερό να είναι σε θερμοκρασία δωματίου. Αν το νερό της βρύσης σου είναι πολύ σκληρό και βλέπεις λευκή κρούστα στο χώμα, διάβασε τον οδηγό για την [ποιότητα του νερού ποτίσματος](/article/poiotita-nerou-potismatos-sklirotita-chlorio-20260919).

**Πώς καταλαβαίνεις αν διψά ή πνίγεται:** και στις δύο περιπτώσεις τα φύλλα κρέμονται. Αν το χώμα είναι στεγνό και τα φύλλα έχουν χάσει τη σφριγηλότητά τους, διψά. Αν το χώμα είναι υγρό για μέρες και τα κάτω φύλλα κιτρινίζουν, πνίγεται. Η δεύτερη είναι πολύ πιο συχνή.

## 4. Χώμα, γλάστρα και μεταφύτευση

**Υπόστρωμα:** ένα ελαφρύ έτοιμο χώμα για εσωτερικά φυτά με 25-30% περλίτη ή φλοιό πεύκου για καλή αποστράγγιση. pH 5,5-7. Το βαρύ, τυρφώδες χώμα που μένει βρεγμένο είναι ο πιο συνηθισμένος λόγος για σήψη ριζών.

**Γλάστρα:** πάντα με τρύπες αποστράγγισης. Το καουτσουκόδεντρο δεν πειράζεται να είναι λίγο «στριμωγμένο» στις ρίζες, οπότε μην το μεταφυτεύεις σε πολύ μεγαλύτερη γλάστρα. Διάλεξε διάμετρο 2-5 εκατοστά μεγαλύτερη.

**Πότε μεταφυτεύεις:** κάθε 2 χρόνια περίπου, στο τέλος του χειμώνα ή την άνοιξη (Μάρτιο-Μάιο), ή όταν οι ρίζες βγαίνουν από τις τρύπες και το χώμα στεγνώνει σε 3-4 ημέρες. Βγάλε το φυτό, χαλάρωσε ελαφρά τις ρίζες και φύτεψέ το στο ίδιο βάθος. Δες τα βήματα και τα λάθη στον [οδηγό αλλαγής γλάστρας](/article/metafyteysi-allagi-glastras-pote-pos-20260916). Στα μεγάλα φυτά, που δεν μεταφυτεύονται εύκολα, αρκεί να αλλάζεις τα πάνω 5 εκατοστά του χώματος κάθε άνοιξη.

## 5. Λίπανση και φροντίδα φύλλων

- **Λίπανση:** από τον Μάρτιο ως τον Σεπτέμβριο, κάθε 3-4 εβδομάδες, με ισορροπημένο υγρό λίπασμα σε **μισή δόση** της ετικέτας. Από τον Οκτώβριο μέχρι τον Φεβρουάριο καθόλου. Το περίσσιο λίπασμα καίει τις ρίζες και αφήνει άλατα στο χώμα.
- **Καθάρισμα:** σκούπισε τα φύλλα με υγρό πανί κάθε 3-4 εβδομάδες. Η σκόνη μειώνει το φως που φτάνει στο φύλλο και κρύβει τα ακάρεα. Μην χρησιμοποιείς λάδι ή «γυαλιστικό» για φύλλα: φράζει τους πόρους.
- **Υγρασία:** δεν χρειάζεται ειδική υγρασία. Ο ξηρός αέρας του καλοριφέρ το ενοχλεί λιγότερο από άλλα φυτά, αλλά επιτρέπει στα ακάρεα να πολλαπλασιάζονται.

## 6. Γιατί πέφτουν τα φύλλα: πίνακας διάγνωσης

| Τι βλέπεις | Πιθανή αιτία | Τι κάνεις |
| :--- | :--- | :--- |
| Πέφτουν πολλά φύλλα μαζί, κάτω και πάνω | Ρεύμα, κρύο, ή απότομη μετακίνηση | Σταθερή θέση, μακριά από παράθυρο που ανοίγει και από κλιματιστικό. Θερμοκρασία πάνω από 15 °C |
| Κίτρινα, μαλακά κάτω φύλλα, χώμα υγρό | Υπερβολικό πότισμα, πιθανή σήψη ριζών | Σταμάτα το πότισμα, έλεγξε τις ρίζες (καφέ και μαλακές = σάπιες), μεταφύτευση σε φρέσκο υπόστρωμα |
| Ένα κάτω φύλλο κιτρινίζει και πέφτει, το φυτό βγάζει νέα | Φυσιολογική γήρανση | Τίποτα. Αφαίρεσε το φύλλο όταν πέσει |
| Φύλλα που κρέμονται, χώμα στεγνό | Δίψα | Πότισμα με το σωστό τρόπο, τα φύλλα ανακάμπτουν σε 1-2 ημέρες |
| Καφέ ξερές άκρες | Άλατα, ξηρό χώμα ή αέρας | Ξέπλυμα του χώματος με άφθονο νερό, πιο τακτικό πότισμα |
| Καφέ κηλίδες με κίτρινο περίγραμμα | Μυκητική ή βακτηριακή κηλίδωση, συνήθως από βρεγμένα φύλλα | Αφαίρεση φύλλων, αποφυγή βρεγμένου φυλλώματος, καλός αερισμός |
| Λευκά ή καφέ σημάδια στην πλευρά του ήλιου | Ηλιακό έγκαυμα | Μετακίνηση σε φωτεινό αλλά χωρίς άμεσο ήλιο |
| Φυτό που γέρνει και μακραίνει με μικρά φύλλα | Λίγο φως | Πιο φωτεινή θέση, γύρισμα της γλάστρας |

Για τα υπόλοιπα φυτά εσωτερικού χώρου (Monstera, Calathea και άλλα) υπάρχει ο [οδηγός φροντίδας εσωτερικών φυτών](/article/guide-15-plant_care), και για τα πιο κοινά ζωύφια ο οδηγός για τα [κοκκοειδή και τον αλευρώδη](/article/kokkoeidi-aleyrodis-antimetopisi-fyta-20261001).

## 7. Κλάδεμα: πώς γίνεται θαμνώδες και όχι γυμνό στη βάση

Αν αφήσεις το καουτσουκόδεντρο χωρίς κλάδεμα, θα γίνει ένα ψηλό, αδύνατο «κοντάρι» με φύλλα μόνο στην κορυφή, γιατί ρίχνει φυσιολογικά τα κάτω φύλλα. Για να το δώσεις πιο φουντωτό:

1. **Πότε:** άνοιξη ή αρχές καλοκαιριού, όταν το φυτό αναπτύσσεται ενεργά.
2. **Πού κόβεις:** πάνω από ένα φύλλο ή κόμπο, στο ύψος που θες να σταματήσει. Από τα μάτια κάτω από την τομή θα βγουν 1-3 νέοι βλαστοί.
3. **Πώς:** με καθαρό, κοφτερό ψαλίδι (σκούπισέ το με οινόπνευμα). Ο λευκός χυμός που τρέχει σταματά αν ακουμπήσεις την τομή με ένα υγρό πανί.
4. **Προστασία:** φόρα γάντια. Ο χυμός είναι ερεθιστικός για το δέρμα και τα μάτια και ελαφρά τοξικός για γάτες και σκύλους. Απομάκρυνε τα κομμένα κομμάτια.

Μια πιο προχωρημένη τεχνική για ψηλά φυτά που έχουν γυμνωθεί είναι ο **αέρινος πολλαπλασιασμός (air layering)**: κάνεις μια μικρή εγκοπή στον κορμό, τη βάζεις σε υγρό σφάγνο (sphagnum) και την τυλίγεις με πλαστικό. Μέσα σε 6-10 εβδομάδες βγαίνουν ρίζες, κόβεις κάτω από αυτές και έχεις ένα νέο φυτό, ενώ το παλιό ξαναβλασταίνει από το κομμένο σημείο.

### Στήριξη όταν γέρνει

Ένα ψηλό καουτσουκόδεντρο που έχει τεντωθεί προς το φως θα γείρει. Μπήξε ένα ξύλινο ή μπαμπού στήριγμα στο χώμα, δίπλα στον κορμό, και δέσε τον κορμό με μαλακό κορδόνι ή ταινία φυτών, χωρίς να σφίξεις. Αν γέρνει επειδή έχει λίγο φως, το στήριγμα λύνει μόνο το σύμπτωμα: πρέπει να το πας πιο κοντά στο παράθυρο και να γυρίζεις τη γλάστρα. Ο κορμός παχαίνει με τον χρόνο, και ένα φυτό που έχει συνηθίσει στο στήριγμα συχνά το ξεχνάει μετά από μία ή δύο εποχές.

## 8. Πολλαπλασιασμός με μοσχεύματα

1. Κόψε μόσχευμα 15-20 εκατοστών με 2-3 φύλλα και τουλάχιστον έναν κόμπο στη βάση, την άνοιξη ή το καλοκαίρι.
2. Άφησε να σταματήσει ο χυμός και βούτηξε τη βάση σε ορμόνη ριζοβολίας (προαιρετικά).
3. Φύτεψε σε μείγμα περλίτη και τύρφης 1:1, ή βάλε σε ποτήρι με νερό. Τύλιξε μεγάλα φύλλα με λαστιχάκι ώστε να μειωθεί η απώλεια νερού.
4. Θερμοκρασία 22-26 °C, φως χωρίς ήλιο. Οι ρίζες εμφανίζονται σε 4-8 εβδομάδες.

Για την τεχνική και τα συνηθισμένα λάθη δες τον [οδηγό πολλαπλασιασμού με μοσχεύματα](/article/pollaplasiasmos-fyton-me-moscheymata-20260909).

## 9. Παράσιτα

- **Τετράνυχος:** λεπτές κίτρινες κουκκίδες στη πάνω πλευρά και ίσως ιστοί στην κάτω, ειδικά σε ζεστό και ξηρό χώρο. Πλύσιμο φύλλων και ψεκασμός με σαπούνι καλίου κάθε 5-7 ημέρες.
- **Ψευδόκοκκοι και κοκκοειδή:** λευκά βαμβακώδη ή καφέ ακίνητα σημεία στα νεύρα και στους μίσχους. Αφαίρεση με μπατονέτα και οινόπνευμα, επανάληψη.
- **Θρίπες:** ασημί γραμμές στα φύλλα. Κολλητικές παγίδες και σαπούνι καλίου.
- **Σήψη ριζών:** μαλακός κορμός στη βάση ή άσχημη μυρωδιά. Αν η σήψη έχει φτάσει στον κορμό, κράτα μοσχεύματα από τα υγιή κομμάτια.

## Πώς διασώζεις ένα φυτό που έχασε τα μισά φύλλα του

Αν το καουτσουκόδεντρό σου έχει μείνει με λίγα φύλλα στην κορυφή, μην πανικοβάλλεσαι: σχεδόν πάντα ανακάμπτει, αρκεί να βρεις την αιτία. Η διαδικασία είναι η εξής:

1. **Βγάλε το φυτό από τη γλάστρα** και κοίταξε τις ρίζες. Οι υγιείς είναι λευκές ή ανοιχτόχρωμες και σφικτές. Οι σάπιες είναι καφέ ή μαύρες, μαλακές και μυρίζουν.
2. **Κόψε τις σάπιες ρίζες** με καθαρό ψαλίδι και φύτεψε σε φρέσκο, στραγγιστό υπόστρωμα, σε γλάστρα ίδιου μεγέθους.
3. **Μην λιπάνεις** μέχρι να βγάλει δύο-τρία νέα φύλλα. Οι πληγωμένες ρίζες δεν απορροφούν λίπασμα και καίγονται.
4. **Βάλε το φυτό σε φωτεινό σημείο χωρίς ήλιο** και πότισε ελάχιστα, μόνο όταν το χώμα στεγνώσει πλήρως στα πρώτα 5 εκατοστά.
5. **Περίμενε.** Το πρώτο νέο φύλλο μπορεί να χρειαστεί 4-8 εβδομάδες το χειμώνα. Κάθε νέο φύλλο είναι σημάδι ότι το φυτό ξανακερδίζει ισχύ.

Αν ο κορμός είναι σκληρός και πράσινος στο εσωτερικό όταν τον γρατζουνίσεις ελαφρά με το νύχι, το φυτό ζει ακόμα, ακόμα και χωρίς φύλλα. Αν είναι καφέ και στεγνός ή μαλακός, το κομμάτι αυτό έχει πεθάνει και κόβεις μέχρι να βρεις πράσινο.

## Χειμώνας με καλοριφέρ και κλιματιστικό

Τον χειμώνα το σπίτι έχει δύο κινδύνους για το φυτό: ο ζεστός ξηρός αέρας του καλοριφέρ και το κρύο ρεύμα από παράθυρο ή μπαλκονόπορτα. Κράτα το καουτσουκόδεντρο τουλάχιστον 50-60 εκατοστά από το καλοριφέρ, και μακριά από σημείο όπου ανοίγει η πόρτα. Τα κρύα τζάμια τη νύχτα μπορεί να ρίξουν τη θερμοκρασία των φύλλων που τα ακουμπούν, οπότε μην αφήνεις τα φύλλα να ακουμπούν στο τζάμι. Το ήπιο, σταθερό περιβάλλον των 16-24 °C είναι το ιδανικό.

## 10. Ποικιλίες

| Ποικιλία | Χαρακτηριστικά |
| :--- | :--- |
| Robusta | Σκούρα πράσινα, μεγάλα, γυαλιστερά φύλλα. Η πιο ανθεκτική και συνηθισμένη |
| Burgundy | Σκούρα μπορντό-πράσινα φύλλα, προτιμά περισσότερο φως |
| Tineke | Παρδαλά φύλλα με κρεμ και ροζ σημεία, χρειάζεται πολύ φως |
| Ruby | Ροζ και κρεμ παρδαλό, πιο ευαίσθητο στο κρύο και στο λίγο φως |

## 11. Ο χρόνος του φυτού

| Περίοδος | Εργασία |
| :--- | :--- |
| Μάρτιος-Απρίλιος | Μεταφύτευση αν χρειάζεται, κλάδεμα, αρχή λίπανσης |
| Μάιος-Αύγουστος | Λίπανση κάθε 3-4 εβδομάδες, καθάρισμα φύλλων, σταθερό πότισμα |
| Σεπτέμβριος | Τελευταία δόση λιπάσματος. Αν ήταν έξω, επιστροφή μέσα πριν κρυώσουν οι νύχτες |
| Οκτώβριος-Φεβρουάριος | Λίγο πότισμα, καθόλου λίπασμα, μακριά από ρεύματα και καλοριφέρ |

## 12. Συχνά λάθη

1. **Υπερβολικό πότισμα**, ειδικά τον χειμώνα.
2. **Μετακίνηση** του φυτού κάθε λίγες ημέρες.
3. **Άμεσος μεσημεριανός ήλιος** πίσω από τζάμι.
4. **Κοντά σε καλοριφέρ ή κλιματιστικό.**
5. **Πολύ μεγάλη γλάστρα** που κρατά νερό.
6. **Λίπασμα τον χειμώνα.**
7. **Κλάδεμα χωρίς γάντια** και χωρίς καθάρισμα του χυμού.

## 13. Συχνές ερωτήσεις

**Είναι τοξικό για γάτες και σκύλους;** Ο γαλακτώδης χυμός του είναι ελαφρά τοξικός και ερεθίζει το στόμα και το δέρμα. Κράτα το σε σημείο που δεν το μασούν.

**Γιατί τα νέα φύλλα έχουν κόκκινο φακελάκι;** Είναι φυσιολογικό: το νέο φύλλο προστατεύεται από ένα κάλυμμα που πέφτει όταν ανοίξει.

**Πρέπει να καθαρίζω τα φύλλα;** Ναι, κάθε 3-4 εβδομάδες με υγρό πανί, χωρίς γυαλιστικά.

**Πόσο γρήγορα μεγαλώνει;** Σε καλό φως και με λίπανση, 30-60 εκατοστά τον χρόνο. Στο σκοτάδι σχεδόν καθόλου.

**Μπορώ να το έχω μόνιμα έξω στην Ελλάδα;** Μόνο σε πολύ ήπιες παραθαλάσσιες περιοχές χωρίς παγετό, σε σκιά. Στις περισσότερες περιοχές μπαίνει μέσα το χειμώνα.

**Πώς το κάνω να βγάλει διακλαδώσεις;** Κλάδεμα πάνω από κόμπο την άνοιξη. Αν δεν θέλεις να κόψεις την κορυφή, μια μικρή εγκοπή λίγο πάνω από έναν κόμπο στον κορμό ενεργοποιεί συχνά ένα νέο βλαστό από εκεί.

**Γιατί το φυτό μου έχει κολλώδη φύλλα;** Συνήθως είναι μελιτώματα από κοκκοειδή ή αλευρώδη. Κοίταξε την κάτω πλευρά των φύλλων και τους μίσχους για μικρά ακίνητα σημεία και καθάρισε με υγρό πανί και σαπούνι καλίου.

**Πόσο συχνά πρέπει να αλλάζω γλάστρα σε ένα μεγάλο φυτό;** Όσο μεγαλώνει, η αλλαγή γίνεται δύσκολη. Όταν η γλάστρα έχει φτάσει τα 35-40 εκατοστά, αρκεί να αντικαθιστάς τα πάνω 5 εκατοστά του χώματος κάθε άνοιξη και να ελέγχεις τις ρίζες κάθε 3-4 χρόνια.

**Τα καφέ φύλλα επανέρχονται;** Όχι. Τα κόβεις αν σε ενοχλούν, ακολουθώντας τη φυσική γραμμή του φύλλου, και διορθώνεις την αιτία.

## 14. Τι κρατάς από όλα

Το καουτσουκόδεντρο είναι από τα πιο εύκολα φυτά εσωτερικού χώρου αν θυμάσαι δύο πράγματα: **σταθερή θέση με φωτεινό, χωρίς καυτό, φως και πότισμα μόνο όταν στεγνώσει το χώμα**. Τα περισσότερα προβλήματα προέρχονται από υπερβολικό νερό ή από απότομες αλλαγές. Και αν μακρύνει και γυμνωθεί, δεν χρειάζεται να το πετάξεις: ένα κλάδεμα την άνοιξη ή ένας αέρινος πολλαπλασιασμός το ξαναφέρνει στην αρχική του φόρμα.
BESPOKE
,
    ),
);

// ==========================================
// 4. LOAD & RESOLVE EXISTING ARTICLES
// ==========================================
$existingArticles = array();
$latestFile = __DIR__ . '/latest_articles.json';

if (file_exists($latestFile)) {
    $rawLatest = @file_get_contents($latestFile);
    $decodedLatest = json_decode($rawLatest, true);
    if (is_array($decodedLatest)) {
        // Two articles carry U+FFFD pairs where a kappa should be, from something upstream
        // re-encoding the JSON a byte at a time. article.php repairs them when it serves a
        // page, but rss.xml is written from this array — so repairing here fixes the stored
        // file the next time the cron rewrites it, and the feed with it.
        require_once __DIR__ . '/ssr-lib.php';
        $existingArticles = array_map('sg_repair_article', $decodedLatest);
    }
}

// ==========================================
// 4b. DEEPEN AN EXISTING THIN ARTICLE
// ==========================================
// AdSense refused the site for "Low value content". Measured against the 74 published
// articles on 2026-09-20, the corpus splits cleanly in two: the 50 inherited from
// master50Articles.ts have a median of 1,174 words and not one reaches 1,450, while all 24
// this cron has written since the floor went in land between 1,881 and 2,318. Two thirds
// of the site is the old set, so that is what a reviewer opens.
//
// Publishing more new articles cannot lift a corpus that is 68% thin — it adds volume,
// which is the pattern that got the site flagged. This rewrites one that already exists,
// in place: same slug, same date, same image, a body that meets the floor for its own
// shape. One per run.
//
//   &deepen=audit           list everything below its floor, generate nothing
//   &deepen=1|<slug>        generate a replacement and return it WITHOUT writing
//   &deepen=...&confirm=1   write it, after taking a dated backup
//
// A plain cron run does it too once the topic pool is exhausted — see section 5.

/** Every published article short of the word floor its own title implies, worst first. */
function sg_deepen_queue(array $articles) {
    $elOf = function ($v) {
        if (is_array($v)) return isset($v['el']) ? (string) $v['el'] : '';
        return is_string($v) ? $v : '';
    };
    $thin = array();
    foreach ($articles as $i => $a) {
        $title = $elOf(isset($a['title']) ? $a['title'] : '');
        if ($title === '') continue;
        // Shape is read off the article's own title, exactly as it would be for a new one,
        // so a diagnosis piece is not held to the floor meant for a species guide.
        $asTopic = array(
            'title' => $title,
            'slug' => isset($a['slug']) ? (string) $a['slug'] : '',
            'category_slug' => isset($a['category']) ? (string) $a['category'] : 'garden',
            'prompt_focus' => $elOf(isset($a['summary']) ? $a['summary'] : ''),
        );
        $words = articleWordCount($elOf(isset($a['content']) ? $a['content'] : ''));
        $floor = sg_word_floor($asTopic);
        if ($words >= $floor) continue;
        $thin[] = array(
            'index' => $i,
            'slug' => $asTopic['slug'],
            'title' => mb_substr($title, 0, 70, 'UTF-8'),
            'shape' => sg_article_shape($asTopic),
            'words' => $words,
            'floor' => $floor,
            'short_by' => $floor - $words,
            'topic' => $asTopic,
        );
    }
    // Worst first: the thinnest article is the one a reviewer is most likely to be shown.
    usort($thin, function ($x, $y) { return $y['short_by'] - $x['short_by']; });
    return $thin;
}

/**
 * Rewrite one thin article in place. Returns array($httpStatus, $payload).
 *
 * $articles is taken by reference because a successful write has to be visible to whatever
 * runs next in the same request — section 5 falls through to here and must not then save a
 * copy of the array from before the rewrite.
 */
function sg_deepen_run(array &$articles, $latestFile, $gemini, $openAi, $want, $confirm) {
    $thin = sg_deepen_queue($articles);

    if ($want === 'audit') {
        $rows = array();
        foreach ($thin as $t) {
            unset($t['topic'], $t['index']);
            $rows[] = $t;
        }
        return array(200, array(
            'success' => true,
            'articlesTotal' => count($articles),
            'belowFloor' => count($thin),
            'queue' => $rows,
        ));
    }

    $target = null;
    foreach ($thin as $t) {
        if ($want === '1' || $t['slug'] === $want) { $target = $t; break; }
    }
    if ($target === null) {
        return array(404, array(
            'success' => false,
            'error' => $want === '1' ? 'Nothing is below its floor.' : 'No article below its floor with slug ' . $want,
            'belowFloor' => count($thin),
        ));
    }

    $fresh = generateScientificAgronomyArticle($target['topic'], $gemini, $openAi);
    $freshWords = articleWordCount($fresh);

    // Never trade a thin article for a thinner one. When every model misses, the generator
    // returns a ~94-word stub, and that stub landing on top of a real article would be far
    // worse than the article was.
    if ($freshWords < $target['floor'] || $freshWords <= $target['words']) {
        return array(422, array(
            'success' => false,
            'error' => 'Replacement did not beat the original; nothing was written.',
            'slug' => $target['slug'],
            'wordsBefore' => $target['words'],
            'wordsGenerated' => $freshWords,
            'floor' => $target['floor'],
        ));
    }

    if (!$confirm) {
        return array(200, array(
            'success' => true,
            'written' => false,
            'note' => 'Dry run. Add &confirm=1 to replace the stored body.',
            'slug' => $target['slug'],
            'shape' => $target['shape'],
            'wordsBefore' => $target['words'],
            'wordsAfter' => $freshWords,
            'preview' => mb_substr($fresh, 0, 600, 'UTF-8'),
        ));
    }

    // One dated backup before the first rewrite of the day. Overwriting this file is how
    // five days of published articles disappeared once already.
    $backup = dirname($latestFile) . '/latest_articles.backup-' . date('Y-m-d') . '.json';
    if (!file_exists($backup)) @copy($latestFile, $backup);

    $at = $target['index'];
    if (isset($articles[$at]['content']) && is_array($articles[$at]['content'])) {
        $articles[$at]['content']['el'] = $fresh;
    } else {
        $articles[$at]['content'] = array('el' => $fresh, 'en' => '');
    }
    $articles[$at]['readTime'] = max(8, (int) round($freshWords / 180)) . ' min';
    $articles[$at]['deepenedAt'] = date('Y-m-d');
    $articles[$at]['wordsBefore'] = $target['words'];

    $encoded = json_encode($articles, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    $tmp = $latestFile . '.tmp';
    $ok = $encoded !== false && @file_put_contents($tmp, $encoded) !== false && @rename($tmp, $latestFile);
    if (!$ok) {
        @unlink($tmp);
        return array(500, array('success' => false, 'error' => 'Could not write latest_articles.json; the article is unchanged.'));
    }

    return array(200, array(
        'success' => true,
        'written' => true,
        'slug' => $target['slug'],
        'shape' => $target['shape'],
        'wordsBefore' => $target['words'],
        'wordsAfter' => $freshWords,
        'backup' => basename($backup),
        'remainingBelowFloor' => count($thin) - 1,
    ));
}

// &shapes=1 reports which shape every topic in the pool would be written to, and stops.
// Changing the skeleton without a way to see the result would mean finding out by reading
// tomorrow's published article.
if (isset($_GET['shapes'])) {
    header('Content-Type: application/json; charset=utf-8');
    $rows = array();
    $tally = array();
    foreach ($topicPool as $t) {
        $shape = sg_article_shape($t);
        $tally[$shape] = (isset($tally[$shape]) ? $tally[$shape] : 0) + 1;
        $rows[] = array(
            'title' => mb_substr($t['title'], 0, 70, 'UTF-8'),
            'shape' => $shape,
            'floorWords' => sg_word_floor($t),
            'sections' => array_map(function ($s) { return $s[0]; }, sg_shape_sections($shape, $t)),
        );
    }
    echo json_encode(array('success' => true, 'tally' => $tally, 'topics' => $rows),
        JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

if (isset($_GET['deepen'])) {
    header('Content-Type: application/json; charset=utf-8');
    list($code, $payload) = sg_deepen_run(
        $existingArticles, $latestFile, $GEMINI_API_KEY, $OPENAI_API_KEY,
        (string) $_GET['deepen'],
        isset($_GET['confirm']) && $_GET['confirm'] === '1'
    );
    if ($code !== 200) http_response_code($code);
    echo json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

// Cap publishing at one article per day. Google's March 2026 core update explicitly
// targeted "scaled content abuse" — sites publishing AI-written articles in volume with
// no human editorial review lost 50-80% of their traffic. This site was on a 3x/day
// cron with zero review, which is the same pattern at a smaller scale. One well-formed
// article a day keeps the pipeline alive without matching the profile Google penalises.
// ?force=1 bypasses this for manual/testing runs.
$forcePublish = isset($_GET['force']) && $_GET['force'] === '1';
if (!$forcePublish) {
    $today = date('Y-m-d');
    foreach ($existingArticles as $existing) {
        if (isset($existing['date']) && $existing['date'] === $today) {
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode(array(
                'success' => false,
                'skipped' => true,
                'reason' => 'An article was already published today (' . $today . '). Daily publishing cap is 1 article/day.',
                'existing_slug' => isset($existing['slug']) ? $existing['slug'] : null,
            ), JSON_UNESCAPED_UNICODE);
            exit;
        }
    }
}

// Select the LEAST-published topic in the pool, not blind round-robin.
// The old formula (topicIndex = totalExisting % count($topicPool)) guaranteed every
// topic got re-published every N articles forever, and once the pool had fully cycled
// more than 4 times the 4-entry $cycleAngles list itself started repeating too — so the
// exact same topic + exact same angle suffix got generated twice, producing genuine
// near-duplicate articles (found and cleaned up 2026-09-08: 22 of 77 articles were
// near-duplicates of just 9 topics). Counting real existing versions per topic and
// capping how many times any one topic can be republished fixes this at the root,
// instead of just deleting the duplicates it produces after the fact.
// One version per topic. At 3 this produced four pairs that differ only in the suffix
// after the colon — «Εσπεριδοειδή σε Γλάστρα …: Προχωρημένος Οδηγός» beside
// «…: Ερωτήσεις & Απαντήσεις», same base title, same subject, and all four second
// versions went out on 2026-09-09 in a burst of eleven. The bodies are genuinely
// different; a reader scanning a category listing, and a reviewer deciding whether this
// is scaled content, sees the same article twice. There is better work for the daily slot
// now: &deepen rewrites one of the 50 thin inherited articles instead.
$MAX_VERSIONS_PER_TOPIC = 1;
// Suffixes read as a natural continuation of the (now hook-style) base title rather
// than a flat format label — "...: Προχωρημένος Οδηγός" read like a filing category,
// not a reason to click, which defeats the point of rewriting the base titles at all.
$cycleAngles = array(
    array('suffix' => 'Τι Αλλάζει στις Δύσκολες Περιπτώσεις', 'focus' => 'Δώσε έμφαση σε προχωρημένες τεχνικές, ειδικές περιπτώσεις και αντιμετώπιση σπάνιων προβλημάτων που δεν καλύπτονται σε βασικό οδηγό.'),
    array('suffix' => 'Τα Λάθη που Κάνουν Όλοι', 'focus' => 'Δώσε έμφαση σε διαγνωστικά συμπτώματα, λάθη αρχαρίων και συγκεκριμένες διορθωτικές ενέργειες βήμα-βήμα.'),
    array('suffix' => 'Πώς Αλλάζει Κάθε Μήνα', 'focus' => 'Δώσε έμφαση σε εποχιακές διαφοροποιήσεις της φροντίδας ανά μήνα και προσαρμογές ανάλογα με το ελληνικό κλίμα.'),
    array('suffix' => 'Οι Πιο Συχνές Ερωτήσεις Αναγνωστών', 'focus' => 'Δόμησε το άρθρο γύρω από τις πιο συχνές ερωτήσεις αναγνωστών με άμεσες, πρακτικές απαντήσεις.'),
);

$topicVersionCounts = array();
foreach ($topicPool as $t) {
    $count = 0;
    foreach ($existingArticles as $existing) {
        $existingSlug = isset($existing['slug']) ? $existing['slug'] : '';
        if ($existingSlug === $t['slug'] || strpos($existingSlug, $t['slug'] . '-') === 0) {
            $count++;
        }
    }
    $topicVersionCounts[$t['slug']] = $count;
}

// Pick the topic with the fewest existing versions that's still under the cap
// (ties broken by original pool order); topics at/over the cap are skipped entirely.
$selectedTopic = null;
$selectedVersionCount = null;
foreach ($topicPool as $t) {
    $c = $topicVersionCounts[$t['slug']];
    if ($c >= $MAX_VERSIONS_PER_TOPIC) continue;
    if ($selectedTopic === null || $c < $selectedVersionCount) {
        $selectedTopic = $t;
        $selectedVersionCount = $c;
    }
}

// The pool has emptied twice without anyone being told, and each time the site went days with
// no new article, Facebook post, pin or video. Mail the owner while there is still time to
// refill it (notify.php sends at most one mail per subject per 12 hours).
$remainingTopics = 0;
foreach ($topicPool as $poolTopic) {
    if ($topicVersionCounts[$poolTopic['slug']] < $MAX_VERSIONS_PER_TOPIC) $remainingTopics++;
}
if ($remainingTopics <= 3) {
    require_once __DIR__ . '/notify.php';
    @sg_notify_failure(
        $remainingTopics === 0
            ? 'SmartGarden: το pool θεμάτων άδειασε, δεν βγαίνουν νέα άρθρα'
            : 'SmartGarden: το pool θεμάτων τελειώνει (' . $remainingTopics . ' αδημοσίευτα)',
        array(
            'Αδημοσίευτα θέματα πριν από αυτή την εκτέλεση: ' . $remainingTopics,
            'Όταν αδειάσει, ο cron ξαναγράφει μόνο παλιά άρθρα και δεν βγαίνει νέο άρθρο, post στο Facebook, pin ή βίντεο.',
            'Χρειάζονται νέα θέματα στο topicPool του public/cron-publish.php.',
        )
    );
}

if ($selectedTopic === null) {
    // Every topic in the pool has been published, so there is no new article to write —
    // and measured against the live set on 2026-09-20 that is true of all 22 of them from
    // the first run onwards. Rather than skip the day, the slot goes to rewriting one of
    // the articles that is below the floor for its shape: 50 of the 74 are, and that is
    // what AdSense read the site as being.
    //
    // This is deliberately the *only* automatic writer of existing articles. It refuses a
    // replacement that misses the floor or fails to beat what it would overwrite, and it
    // copies latest_articles.json to a dated backup before the first rewrite of any day.
    // &nodeepen=1 turns it off for a run, and the pool getting new topics ends it.
    header('Content-Type: application/json; charset=utf-8');

    if (isset($_GET['nodeepen']) && $_GET['nodeepen'] === '1') {
        echo json_encode(array(
            'success' => false,
            'skipped' => true,
            'reason' => 'Every topic in topicPool has been published (cap ' . $MAX_VERSIONS_PER_TOPIC . ') and &nodeepen=1 was given.',
            'topicVersionCounts' => $topicVersionCounts,
        ), JSON_UNESCAPED_UNICODE);
        exit;
    }

    // The daily-publish cap above only ever checked an article's own `date`, which a
    // deepen never touches — so this branch had no throttle of its own, and cron-job.org
    // pinging more than once a day meant more than one rewrite a day (three on
    // 2026-09-09... 2026-09-22, once the pool ran out). Explicit now, at 3: a deepen never
    // adds a URL — 74 stays 74 — so the "many new pages" pattern the March 2026 core
    // update penalised doesn't apply the way it does to new articles. 3/day still finishes
    // the 44-article backlog in under three weeks instead of forty-four days.
    // &maxdeepen= overrides it for a manual run.
    $maxDeepenPerDay = isset($_GET['maxdeepen']) ? max(0, (int) $_GET['maxdeepen']) : 3;
    $today = date('Y-m-d');
    $deepenedToday = 0;
    foreach ($existingArticles as $existing) {
        if (isset($existing['deepenedAt']) && $existing['deepenedAt'] === $today) $deepenedToday++;
    }
    if ($deepenedToday >= $maxDeepenPerDay) {
        echo json_encode(array(
            'success' => false,
            'skipped' => true,
            'reason' => 'Daily deepen cap reached (' . $deepenedToday . '/' . $maxDeepenPerDay . ' today).',
            'deepenedToday' => $deepenedToday,
            'maxDeepenPerDay' => $maxDeepenPerDay,
        ), JSON_UNESCAPED_UNICODE);
        exit;
    }

    list($deepenCode, $deepenPayload) = sg_deepen_run(
        $existingArticles, $latestFile, $GEMINI_API_KEY, $OPENAI_API_KEY, '1', true
    );
    if ($deepenCode !== 200) http_response_code($deepenCode);
    echo json_encode(array_merge(array(
        'mode' => 'deepen',
        'reason' => 'Topic pool exhausted (cap ' . $MAX_VERSIONS_PER_TOPIC . '); the daily slot rewrote an existing article instead of publishing a new one.',
    ), $deepenPayload), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}



// This topic already has at least one prior version — give this one a distinct angle
// (based on how many versions THIS topic has, not a global counter) so it reads as a
// genuinely different article instead of a near-clone.
if ($selectedVersionCount > 0) {
    $angle = $cycleAngles[($selectedVersionCount - 1) % count($cycleAngles)];
    $selectedTopic['title'] = $selectedTopic['title'] . ': ' . $angle['suffix'];
    $selectedTopic['prompt_focus'] = $selectedTopic['prompt_focus'] . "\n\nΣΗΜΑΝΤΙΚΟ: " . $angle['focus'] . ' Απόφυγε να επαναλάβεις αυτολεξεί προηγούμενο άρθρο με τον ίδιο βασικό τίτλο — αυτό είναι νέο, διαφορετικό άρθρο με νέα γωνία θέασης.';
}

// ==========================================
// 5. AI ENGINE: GENERATE SCIENTIFIC AGRONOMY CONTENT
// ==========================================
function articleWordCount($content) {
    preg_match_all('/[\p{L}\p{N}]+(?:[\x{2019}\x{2018}\'-][\p{L}\p{N}]+)*/u', $content, $matches);
    return count($matches[0]);
}

function callGeminiModel($url, $postData, $timeoutSeconds) {
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, $postData);
    curl_setopt($ch, CURLOPT_HTTPHEADER, array('Content-Type: application/json'));
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 5);
    curl_setopt($ch, CURLOPT_TIMEOUT, $timeoutSeconds);
    return $ch;
}

function extractGeminiText($result, $httpCode) {
    if ($httpCode !== 200 || empty($result)) {
        return '';
    }
    $json = json_decode($result, true);
    return isset($json['candidates'][0]['content']['parts'][0]['text']) ? $json['candidates'][0]['content']['parts'][0]['text'] : '';
}

$GLOBALS['cronDebug'] = array();

/**
 * Which shape of article this topic wants.
 *
 * Every article used to be written to one hardcoded skeleton — Σύντομη Απάντηση, then
 * "1. Επιστημονικό Υπόβαθρο & Βοτανική Φυσιολογία", "2. Τεχνικές Προδιαγραφές & Πίνακας
 * Παραμέτρων", and four more, identical across all 73 of them. A guide to a beginner's
 * hand tools got a section on cell physiology and a parameter table with pH and EC, because
 * the template said so. On 2026-09-19 AdSense rejected the site for "Low value content",
 * citing its spam policy on scaled content; 73 pages sharing one skeleton is exactly the
 * shape that policy describes, whoever or whatever wrote them.
 *
 * The shape is chosen from the topic itself and is deterministic, so re-running an article
 * produces the same structure rather than a random one.
 */
function sg_article_shape($topic, &$score = null) {
    // Scored, not first-match. An ordered if-chain lets one incidental word decide: the
    // lemon-tree piece is a diagnosis of yellow leaves, but its brief happens to mention
    // "διαφορά EDDHA vs EDTA" and a choice-first chain filed it as a comparison. The title
    // says what an article IS, so it counts triple; the brief only breaks ties.
    $title = mb_strtolower((string) ($topic['title'] ?? ''), 'UTF-8');
    $focus = mb_strtolower((string) ($topic['prompt_focus'] ?? ''), 'UTF-8');

    $keywords = array(
        'list'      => array('λάθη', 'σφάλματα', 'μύθοι', 'τα 10 ', 'τα 7 ', 'τα 5 ', 'λίστα'),
        'choice'    => array('εργαλεί', 'σύγκρισ', ' vs ', 'ποιο ', 'επιλογή', 'μάρκ', 'αγοράσ', 'διαλέξ'),
        'diagnosis' => array('γιατί', 'κιτριν', 'μαραίν', 'σήψη', 'ασθέν', 'προσβολ', 'αποκατάστασ', 'τροφοπεν', 'δεν φταίει', 'νεκρό', 'ξεραίν'),
        'howto'     => array('πώς ', 'βήμα', 'μεταφύτευσ', 'φύτευσ', 'πολλαπλασιασμ', 'εγκατάστασ', 'κλάδεμα', 'κομποστ', 'τεστ', 'φτιάχν'),
        'species'   => array('καλλιέργεια', 'φροντίδα', 'ποικιλί', 'σπορά', 'ημερολόγιο'),
    );

    $best = 'species';
    $bestScore = 0;
    foreach ($keywords as $shape => $needles) {
        $score = 0;
        foreach ($needles as $n) {
            if (mb_strpos($title, $n, 0, 'UTF-8') !== false) $score += 3;
            if (mb_strpos($focus, $n, 0, 'UTF-8') !== false) $score += 1;
        }
        if ($score > $bestScore) { $bestScore = $score; $best = $shape; }
    }
    // Reported so a caller can tell a real classification from the fallback: 'species' is
    // both a genuine shape and what an unrecognised title lands on.
    $score = $bestScore;
    return $best;
}

/**
 * The sections for a shape: heading plus the brief the model is given for it.
 *
 * A parameter table appears only where the topic actually has parameters — a topic whose
 * temp is "N/A" is a tools or technique piece, and a table of pH and EC on it is noise that
 * announces the template.
 */
function sg_shape_sections($shape, $topic) {
    $hasParams = !empty($topic['temp']) && $topic['temp'] !== 'N/A'
              && !empty($topic['ph']) && $topic['ph'] !== 'N/A';


    // Read defensively: a topic added later without these keys must not emit warnings into
    // the response body, which is JSON the scheduler parses.
    $ph = isset($topic['ph']) ? $topic['ph'] : 'N/A';
    $ec = isset($topic['ec']) ? $topic['ec'] : 'N/A';
    $temp = isset($topic['temp']) ? $topic['temp'] : 'N/A';

    $table = "Δημιούργησε έναν πλήρη πίνακα Markdown με τις στήλες: Παράμετρος | Βέλτιστη Τιμή | Μονάδα | Παρατηρήσεις. "
           . "Συμπερίλαβε pH υποστρώματος {$ph}, EC {$ec}, θερμοκρασία {$temp}°C "
           . "και όσες ακόμη παραμέτρους έχουν νόημα για το συγκεκριμένο θέμα.";

    switch ($shape) {
        case 'diagnosis':
            return array(
                array('Σύντομη Απάντηση', ''),
                array('Τι ακριβώς βλέπεις', 'Περίγραψε τα ορατά συμπτώματα με λεπτομέρεια, ώστε ο αναγνώστης να αναγνωρίσει αν αυτό έχει. Ξεχώρισέ τα από παρόμοια συμπτώματα με άλλη αιτία.'),
                array('Γιατί συμβαίνει', 'Ο μηχανισμός πίσω από το σύμπτωμα: τι κάνει το φυτό και γιατί. Συγκεκριμένα, όχι γενικόλογα.'),
                array('Τι κάνεις τώρα', 'Άμεσες ενέργειες με σειρά προτεραιότητας, δοσολογίες και χρόνους. Τι κάνεις σήμερα, τι την επόμενη εβδομάδα.'),
                array('Πώς δεν θα ξανασυμβεί', 'Η πρακτική αλλαγή που κλείνει το θέμα μόνιμα.'),
            );
        case 'howto':
            return array(
                array('Σύντομη Απάντηση', ''),
                array('Πότε είναι η σωστή στιγμή', 'Εποχή, στάδιο του φυτού, καιρικές συνθήκες — και πότε ΔΕΝ πρέπει να γίνει.'),
                array('Τι χρειάζεσαι', 'Υλικά και εργαλεία με συγκεκριμένες προδιαγραφές και ποσότητες.'),
                array('Η διαδικασία, βήμα προς βήμα', 'Αριθμημένα βήματα με ακρίβεια: μετρήσεις, χρόνοι, τεχνική. Το πιο εκτενές τμήμα του άρθρου.'),
                array('Οι πρώτες εβδομάδες μετά', 'Πρόγραμμα φροντίδας με χρονοδιάγραμμα, και τι είναι φυσιολογικό να δεις.'),
                array('Τι πάει στραβά και πώς το αποφεύγεις', 'Τα κρίσιμα σφάλματα σε αυτή τη συγκεκριμένη διαδικασία.'),
            );
        case 'choice':
            return array(
                array('Σύντομη Απάντηση', ''),
                array('Το ερώτημα πίσω από την επιλογή', 'Τι πραγματικά διαφοροποιεί τις επιλογές, πέρα από την τιμή.'),
                array('Οι επιλογές, μία προς μία', 'Κάθε επιλογή με τα πραγματικά της πλεονεκτήματα και μειονεκτήματα, με τεχνικά στοιχεία.'),
                array('Πίνακας σύγκρισης', 'Πίνακας Markdown που συγκρίνει τις επιλογές στα κριτήρια που μετράνε.'),
                array('Τι διαλέγεις για κάθε περίπτωση', 'Συγκεκριμένες συστάσεις ανά σενάριο χρήσης, με ονόματα και μεγέθη.'),
                array('Τι ΔΕΝ χρειάζεσαι', 'Τι είναι περιττό ή υπερτιμημένο, και γιατί.'),
            );
        case 'list':
            return array(
                array('Σύντομη Απάντηση', ''),
                array('Γιατί έχει σημασία', 'Το πλαίσιο: τι διακυβεύεται αν αγνοηθούν αυτά.'),
                array('Ένα προς ένα', 'Το κύριο σώμα. Για κάθε σημείο: τι είναι, γιατί συμβαίνει, τι κάνεις αντ αυτού. Αριθμημένο, εκτενές, με συγκεκριμένα νούμερα.'),
                array('Τι κρατάς από όλα', 'Η μία πρακτική αλλαγή που αξίζει περισσότερο από τις υπόλοιπες.'),
            );
        default: // species
            return array_values(array_filter(array(
                array('Σύντομη Απάντηση', ''),
                array('Τι θέλει πραγματικά αυτό το φυτό', 'Φως, νερό, υπόστρωμα και θερμοκρασία με πραγματικά νούμερα, και η φυσιολογία που τα εξηγεί.'),
                $hasParams ? array('Πίνακας προδιαγραφών', $table) : null,
                array('Η χρονιά, μήνα με μήνα', 'Ημερολόγιο εργασιών ανά εποχή για το ελληνικό κλίμα.'),
                array('Προβλήματα και αντιμετώπιση', 'Οι πραγματικές απειλές για αυτό το είδος, με βιολογικές λύσεις και δοσολογίες.'),
                array('Συχνά λάθη', 'Τι κάνουν λάθος οι περισσότεροι με αυτό το συγκεκριμένο φυτό.'),
            )));
    }
}

/**
 * The shortest this shape of article may be and still publish.
 *
 * A single hardcoded 2,000-word floor was the other half of the template problem: it made
 * every piece the same length as well as the same shape, and a diagnosis that has said
 * everything worth saying in 1,600 words had to be padded to clear it. Padding is what
 * "low value" looks like from the outside. The floor is about 85% of the shape's target,
 * never below 1,400 — under that it genuinely is thin.
 */
function sg_word_floor($topic) {
    $floors = array('diagnosis' => 1450, 'howto' => 1800, 'choice' => 1600, 'list' => 1550, 'species' => 1900);
    $score = 0;
    $shape = sg_article_shape($topic, $score);
    // Nothing in the title said what this article is, so it defaulted to 'species' — which
    // carries the highest floor of the five. Holding an unclassifiable subject to the
    // strictest bar is backwards; it gets the neutral middle instead.
    if ($score === 0) return 1700;
    return isset($floors[$shape]) ? $floors[$shape] : 1700;
}

function generateScientificAgronomyArticle($topic, $geminiKey, $openAiKey) {
    // A hand-written article beats a generated one: a person has read it, it costs no API call
    // and it cannot miss the word floor on a bad Gemini day. Generation remains for topics
    // that ship without one.
    if (!empty($topic['bespoke_article']) && articleWordCount($topic['bespoke_article']) >= 2200) {
        return $topic['bespoke_article'];
    }

    // 1. Try Gemini API if key is present
    if (!empty($geminiKey)) {
        // cron-job.org has a hard 30-second request limit. Keep enough time to
        // return a useful error response instead of letting the caller time out.
        // Two flash-lite rounds measured ~18-20s combined (2026-09-04), so 28s leaves a
        // small buffer while still allowing the retry round to actually run.
        $generationDeadline = microtime(true) + 28;

        $sharedIntro = "Είσαι ο κορυφαίος Έλληνας καθηγητής Γεωπονίας και συντάκτης του SmartGarden.gr. Γράφεις ένα επιστημονικά άρτιο άρθρο στα Ελληνικά με τίτλο: '{$topic['title']}'.\n"
            . "Εστίαση θέματος:\n{$topic['prompt_focus']}\n\n";

        // The skeleton now comes from the topic, not from this file. See sg_article_shape().
        $shape = sg_article_shape($topic);
        $sections = sg_shape_sections($shape, $topic);

        // The answer-first block is the one section every shape keeps. AI search engines
        // (ChatGPT, Perplexity, Google AI Overviews) cite self-contained blocks that open
        // with the direct answer and concrete numbers; human readers otherwise hit 450
        // words of botany before the practical answer.
        $answerBrief = "3-5 προτάσεις που απαντούν ΑΜΕΣΑ και αυτοτελώς στο βασικό ερώτημα του τίτλου, "
            . "ΠΡΙΝ από κάθε θεωρία. Ξεκίνα με την απάντηση, όχι με εισαγωγή. Χρησιμοποίησε συγκεκριμένους "
            . "αριθμούς αντί για γενικόλογες διατυπώσεις όπως «αρκετό» ή «τακτικά». Πρέπει να στέκει μόνη της.";

        $render = function ($slice) use ($answerBrief) {
            $out = '';
            foreach ($slice as $s) {
                $out .= '## ' . $s[0] . "\n" . ($s[1] !== '' ? $s[1] : $answerBrief) . "\n\n";
            }
            return $out;
        };

        // Split the sections across the two parallel requests, keeping the answer block and
        // the opening sections together in the first.
        $half = (int) ceil(count($sections) / 2);
        $firstHalf = array_slice($sections, 0, $half);
        $secondHalf = array_slice($sections, $half);

        // Length varies by shape too — a diagnosis piece that runs as long as a full species
        // guide is padding, and padding is what "low value" means.
        $targets = array('diagnosis' => 1700, 'howto' => 2100, 'choice' => 1900, 'list' => 1800, 'species' => 2200);
        $target = isset($targets[$shape]) ? $targets[$shape] : 2000;
        $halfTarget = (int) round($target / 2 / 50) * 50;

        $rules = "Γράψε σε δεύτερο πρόσωπο, απευθυνόμενος στον αναγνώστη. Απόφυγε τις φράσεις «είναι σημαντικό», "
            . "«παίζει καθοριστικό ρόλο» και «αποτελεί κρίσιμο παράγοντα» — πες τι συμβαίνει και τι να κάνει. "
            . "Κάθε ισχυρισμός με νούμερο: δόση, θερμοκρασία, ημέρες, εκατοστά.";

        $promptA = $sharedIntro
            . "Γράψε ΜΟΝΟ τις εξής ενότητες σε Markdown (##), με αυτούς ακριβώς τους τίτλους και με αυτή τη σειρά. "
            . "Ανάπτυξε διεξοδικά, μη συνοψίζεις.\n\n"
            . $render($firstHalf)
            . $rules . "\n"
            . "Συνολικά τουλάχιστον {$halfTarget} λέξεις. Γράψε ΜΟΝΟ το κείμενο, χωρίς μετα-σχόλια.";

        $promptB = $sharedIntro
            . "Συνεχίζεις το ΙΔΙΟ άρθρο. ΜΗΝ επαναλάβεις τίτλο, εισαγωγή ή τις προηγούμενες ενότητες. "
            . "Γράψε ΜΟΝΟ τις εξής ενότητες σε Markdown (##), με αυτούς ακριβώς τους τίτλους και με αυτή τη σειρά. "
            . "Ανάπτυξε διεξοδικά, μη συνοψίζεις.\n\n"
            . $render($secondHalf)
            . $rules . "\n"
            . "Συνολικά τουλάχιστον {$halfTarget} λέξεις. Γράψε ΜΟΝΟ το κείμενο, χωρίς μετα-σχόλια.";

        $genConfig = array("temperature" => 0.7, "maxOutputTokens" => 8192);
        $postA = json_encode(array("contents" => array(array("parts" => array(array("text" => $promptA)))), "generationConfig" => $genConfig));
        $postB = json_encode(array("contents" => array(array("parts" => array(array("text" => $promptB)))), "generationConfig" => $genConfig));

        // gemini-3.1-flash-lite answers in ~10-20s with no extended "thinking" step, unlike
        // gemini-flash-latest/3.7-flash (reasoning models that take 30-60s+ and frequently
        // 503 under load — both regularly blew the cron's ~24s budget as of 2026-09-04).
        // But asked for a full 2,300-2,600 word article in one shot, flash-lite stops early
        // around ~1,200 words. Splitting the article into two halves and firing them at the
        // SAME time via curl_multi keeps wall time ~15-20s per round while each half lands
        // near its own (achievable) target. Even so it consistently undershoots the asked
        // word count by ~20-25% (measured 2026-09-04), so retry the same reliable model
        // (not a different, unverified model name) once more if the first round falls short —
        // two rounds still comfortably fit inside the cron's ~24-27s budget.
        $model = 'gemini-3.1-flash-lite';
        for ($attempt = 0; $attempt < 2; $attempt++) {
            $secondsRemaining = (int)floor($generationDeadline - microtime(true));
            // A full round takes ~15-20s; don't start one that can't finish before the
            // deadline — a doomed retry just burns the budget the fallback needs (2026-09-04).
            $minSecondsForRound = $attempt === 0 ? 4 : 12;
            if ($secondsRemaining < $minSecondsForRound) {
                break;
            }
            $timeoutSeconds = min(22, $secondsRemaining);
            $url = "https://generativelanguage.googleapis.com/v1beta/models/" . $model . ":generateContent?key=" . $geminiKey;

            $mh = curl_multi_init();
            $chA = callGeminiModel($url, $postA, $timeoutSeconds);
            $chB = callGeminiModel($url, $postB, $timeoutSeconds);
            curl_multi_add_handle($mh, $chA);
            curl_multi_add_handle($mh, $chB);

            $running = null;
            $multiErrors = array();
            do {
                curl_multi_exec($mh, $running);
                while ($info = curl_multi_info_read($mh)) {
                    if ($info['result'] !== CURLE_OK) {
                        $multiErrors[] = curl_strerror($info['result']) . ' (errno ' . $info['result'] . ')';
                    }
                }
                if ($running > 0) {
                    curl_multi_select($mh, 1);
                }
            } while ($running > 0);

            $rawA = curl_multi_getcontent($chA);
            $rawB = curl_multi_getcontent($chB);
            $codeA = curl_getinfo($chA, CURLINFO_HTTP_CODE);
            $codeB = curl_getinfo($chB, CURLINFO_HTTP_CODE);

            // Gemini reports its token usage on every response and it was being thrown away,
            // so the marginal cost of an article was unknowable without opening Google's
            // billing console. Both halves are counted: an article comes from two parallel
            // calls and totalling one would halve the answer. Best-effort by design.
            require_once __DIR__ . '/usage-ledger.php';
            @sg_record_usage(array($rawA, $rawB), $model, $topic['slug'] ?? '');
            $textA = extractGeminiText($rawA, $codeA);
            $textB = extractGeminiText($rawB, $codeB);

            $combinedForDebug = trim($textA) . "\n\n" . trim($textB);
            $GLOBALS['cronDebug'][] = array(
                'model' => $model, 'attempt' => $attempt, 'multiErrors' => $multiErrors,
                'codeA' => $codeA, 'lenA' => strlen($textA), 'wordsA' => articleWordCount($textA),
                'codeB' => $codeB, 'lenB' => strlen($textB), 'wordsB' => articleWordCount($textB),
                'wordsCombined' => articleWordCount($combinedForDebug),
            );

            curl_multi_remove_handle($mh, $chA);
            curl_multi_remove_handle($mh, $chB);
            curl_multi_close($mh);
            curl_close($chA);
            curl_close($chB);

            if (!empty($textA) && !empty($textB)) {
                $combined = trim($textA) . "\n\n" . trim($textB);
                // 2,000 words (not 2,200) is the real-world acceptance floor: flash-lite's
                // output naturally lands in the ~2,000-2,300 range, and a solid ~2,000-word
                // AI article beats discarding good content over a ~100-word technicality
                // and falling back to the ~94-word generic stub (2026-09-04).
                if (articleWordCount($combined) >= sg_word_floor($topic)) {
                    return $combined;
                }
            }
        }

        // Fallback: one single-shot request against the slower/less reliable reasoning
        // models, only if there's still meaningful time left in the budget.
        $secondsRemaining = (int)floor($generationDeadline - microtime(true));
        if ($secondsRemaining >= 8) {
            $singlePrompt = $sharedIntro
                . "Γράψε ένα εξαιρετικά αναλυτικό, επιστημονικά άρτιο και πρακτικό άρθρο 2.300 έως 2.600 λέξεων, με την εξής υποχρεωτική δομή:\n\n"
                . "## Σύντομη Απάντηση\n(3-5 προτάσεις που απαντούν ΑΜΕΣΑ και αυτοτελώς στο ερώτημα του τίτλου, με συγκεκριμένους αριθμούς αντί για γενικόλογες διατυπώσεις, ΠΡΙΝ από κάθε θεωρία.)\n"
                . "## 1. Επιστημονικό Υπόβαθρο & Βοτανική Φυσιολογία\n## 2. Τεχνικές Προδιαγραφές & Πίνακας Παραμέτρων\n## 3. Βήμα-προς-Βήμα Μεθοδολογία & Εφαρμογή\n"
                . "## 4. Ολοκληρωμένη Βιολογική Φυτοπροστασία / Τεχνολογική Διάταξη\n## 5. Πρόγραμμα Θρέψης, Άρδευσης & Συντήρησης\n## 6. Συχνότερα Λάθη & Οδηγίες Αποφυγής\n\n"
                . "Γράψε ΜΟΝΟ το κυρίως κείμενο του άρθρου σε Markdown. Το τελικό άρθρο πρέπει υποχρεωτικά να έχει τουλάχιστον 2.200 λέξεις. Χωρίς εισαγωγικά μετα-σχόλια.";
            $postSingle = json_encode(array("contents" => array(array("parts" => array(array("text" => $singlePrompt)))), "generationConfig" => $genConfig));

            $candidateModels = array('gemini-3.5-flash', 'gemini-flash-latest', 'gemini-3.7-flash');
            foreach ($candidateModels as $model) {
                $secondsRemaining = (int)floor($generationDeadline - microtime(true));
                if ($secondsRemaining < 2) {
                    break;
                }
                $url = "https://generativelanguage.googleapis.com/v1beta/models/" . $model . ":generateContent?key=" . $geminiKey;
                $ch = callGeminiModel($url, $postSingle, min(20, $secondsRemaining));
                $result = curl_exec($ch);
                $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
                curl_close($ch);

                $content = extractGeminiText($result, $httpCode);
                if (!empty($content) && articleWordCount($content) >= sg_word_floor($topic)) {
                    return $content;
                }
            }
        }
    }

    // 2. BESPOKE SCIENTIFIC AGRONOMY CATALOG FALLBACK (100% Tailored)
    if (!empty($topic['bespoke_article']) && articleWordCount($topic['bespoke_article']) >= 2200) {
        return $topic['bespoke_article'];
    }

    return "## 1. Επιστημονικό Υπόβαθρο & Βοτανική Φυσιολογία\n\n"
         . "Η σωστή διαχείριση στο θέμα «{$topic['title']}» αποτελεί ακρογωνιαίο λίθο της σύγχρονης αστικής και εφαρμοσμένης γεωπονίας.\n\n"
         . "## 2. Τεχνικές Προδιαγραφές & Πίνακας Παραμέτρων\n\n"
         . "| Παράμετρος Εφαρμογής | Βέλτιστη Τιμή | Μονάδα Μέτρησης | Παρατηρήσεις |\n"
         . "| :--- | :--- | :--- | :--- |\n"
         . "| **Βοτανική Ταξινόμηση** | *{$topic['botanical']}* | - | Επιστημονική ονομασία |\n"
         . "| **Εύρος pH Υποστρώματος** | {$topic['ph']} | pH | Βέλτιστη διαθεσιμότητα θρεπτικών |\n"
         . "| **Ηλεκτρική Αγωγιμότητα (EC)** | {$topic['ec']} | mS/cm | Αποφυγή τοξικότητας αλάτων |\n"
         . "| **Θερμοκρασία Ανάπτυξης** | {$topic['temp']} | °C | Μέγιστος μεταβολικός ρυθμός |\n\n";
}

// Generate Content
$generatedContent = generateScientificAgronomyArticle($selectedTopic, $GEMINI_API_KEY, $OPENAI_API_KEY);
$generatedWordCount = articleWordCount($generatedContent);

if (isset($_GET['debug'])) {
    http_response_code(200);
    echo json_encode(array(
        'word_count' => $generatedWordCount,
        'content_preview' => mb_substr($generatedContent, 0, 150),
        'debug' => $GLOBALS['cronDebug']
    ), JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT | JSON_INVALID_UTF8_SUBSTITUTE);
    exit;
}

// Never let a thin AI response become a live article. Returning a non-2xx
// response means the scheduler can report the failed generation and retry later.
// Floor is 2,000, not 2,200 — matches the acceptance floor inside
// generateScientificAgronomyArticle() (see 2026-09-04 notes there).
if ($generatedWordCount < sg_word_floor($selectedTopic)) {
    http_response_code(422);
    echo json_encode(array(
        'status' => 'error',
        'message' => 'Article was not published because it did not reach the minimum for its shape ('
                   . sg_article_shape($selectedTopic) . ': ' . sg_word_floor($selectedTopic) . ' words).',
        'topic_slug' => $selectedTopic['slug'],
        'word_count' => $generatedWordCount
    ), JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
    exit;
}

// ==========================================
// 6. WORDPRESS SYNC (If WP is active)
// ==========================================
$wpPostId = null;
if ($wpLoaded) {
    // Map categories
    $catId = 1;
    $term = get_term_by('slug', $selectedTopic['category_slug'], 'category');
    if ($term) {
        $catId = $term->term_id;
    }

    $postData = array(
        'post_title'    => wp_strip_all_tags($selectedTopic['title']),
        'post_name'     => $selectedTopic['slug'] . '-' . date('Ymd-Hi'),
        'post_content'  => $generatedContent,
        'post_status'   => 'publish',
        'post_author'   => 1,
        'post_category' => array($catId)
    );

    $insertedId = wp_insert_post($postData);
    if (!is_wp_error($insertedId) && $insertedId > 0) {
        $wpPostId = $insertedId;
        update_post_meta($insertedId, 'smartgarden_generated', 'true');
        update_post_meta($insertedId, 'smartgarden_read_time', $selectedTopic['readTime']);
        update_post_meta($insertedId, 'smartgarden_difficulty', $selectedTopic['difficulty']);
    }
}

// ==========================================
// 7. SYNC TO STANDALONE JSON STORAGE
// ==========================================
$newArticleObj = array(
    "id" => "art-auto-" . date('Ymd-His') . "-" . substr(md5(uniqid()), 0, 6),
    "slug" => $selectedTopic['slug'] . '-' . date('Ymd'),
    "title" => array(
        "el" => $selectedTopic['title'],
        "en" => $selectedTopic['title'] . " (Agronomy Guide)"
    ),
    "summary" => array(
        "el" => $selectedTopic['summary'],
        "en" => "Comprehensive scientific agronomy guide for urban Mediterranean gardening and precision horticulture."
    ),
    "content" => array(
        "el" => $generatedContent,
        "en" => $generatedContent
    ),
    "category" => $selectedTopic['category_slug'],
    "categoryLabel" => array(
        "el" => $selectedTopic['category'],
        "en" => $selectedTopic['category']
    ),
    "readTime" => $selectedTopic['readTime'],
    "difficulty" => $selectedTopic['difficulty'],
    "difficultyLabel" => array(
        "el" => $selectedTopic['difficultyLabel'],
        "en" => $selectedTopic['difficultyLabel']
    ),
    "author" => array(
        "name" => "Κώστας Αναστασιάδης",
        "role" => array(
            "el" => "Γεωπόνος & IoT Specialist",
            "en" => "Agronomist & IoT Specialist"
        ),
        "avatar" => "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=120&auto=format&fit=crop&q=80"
    ),
    "image" => $selectedTopic['image'],
    "date" => date('Y-m-d'),
    "dateFormatted" => array(
        "el" => $greekDateFormatted,
        "en" => date('F j, Y')
    ),
    "keyTakeaways" => array(
        "el" => $selectedTopic['keyTakeaways'],
        "en" => $selectedTopic['keyTakeaways']
    ),
    "featured" => false,
    "tags" => array("Γεωπονία", "Οικολογική Φροντίδα", "Smart Garden", "Αστική Καλλιέργεια")
);

// Prepend to catalog and save
array_unshift($existingArticles, $newArticleObj);

// Limit catalog to 100 entries to prevent memory overflow
if (count($existingArticles) > 100) {
    $existingArticles = array_slice($existingArticles, 0, 100);
}

@file_put_contents($latestFile, json_encode($existingArticles, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));

// Auto-share the freshly published article to the Facebook Page as a link post —
// Facebook renders its own preview card from the article's OG title/description/
// image (via article.php), so this is deliberately just a link + short caption,
// not a duplicate of the article body.
//
// Re-enabled 2026-09-29 after the 2026-09-09 lockout was resolved (the Page itself was
// locked for posting too fast; separately, the developer account had its own "Account
// confirmation needed" hold, cleared the same day via phone/WhatsApp verification — both
// confirmed fixed with a live read-only Graph API call before this was turned back on).
// The trigger the first time was a burst of ~10 auto-posts within ~15 minutes on one day —
// nothing before ever actually throttled this block, it fired on every single new-article
// publish. A marker file is the fix: at most one Facebook post per calendar day, mirroring
// the deepen cap's per-day counter and [[feedback-video-publish-rate]]'s one-topic/day rule.
// Never remove this guard to "just flip it back on" again.
define('FB_AUTO_POST_ENABLED', true);
$fbPageId = getenv('FACEBOOK_PAGE_ID');
$fbPageToken = getenv('FACEBOOK_PAGE_ACCESS_TOKEN');
$fbMarkerFile = __DIR__ . '/facebook-last-post.json';
// Defined locally rather than reusing $today from the deepen branch above: that branch
// exits before this new-article path is ever reached, so $today would be undefined here.
$fbToday = date('Y-m-d');
$fbAlreadyPostedToday = false;
$fbMarker = json_decode((string) @file_get_contents($fbMarkerFile), true);
if (is_array($fbMarker) && ($fbMarker['date'] ?? '') === $fbToday) $fbAlreadyPostedToday = true;

if (FB_AUTO_POST_ENABLED && $fbPageId && $fbPageToken && !$fbAlreadyPostedToday) {
    $articleUrl = 'https://smartgarden.gr/article/' . rawurlencode($newArticleObj['slug']);
    $fbCh = curl_init("https://graph.facebook.com/v26.0/{$fbPageId}/feed");
    curl_setopt_array($fbCh, array(
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => http_build_query(array(
            'message' => $newArticleObj['title']['el'],
            'link' => $articleUrl,
            'access_token' => $fbPageToken,
        )),
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 15,
    ));
    $fbResp = curl_exec($fbCh); // best-effort — a Facebook hiccup must never fail article publishing
    $fbHttpCode = curl_getinfo($fbCh, CURLINFO_HTTP_CODE);
    curl_close($fbCh);
    // Only mark today as "done" on an actual successful post (2xx with an id back) — a
    // failed attempt (Page down, token expired) must not burn the day's one slot, or a
    // real outage would silently cancel that day's post with no retry.
    $fbDecoded = json_decode((string) $fbResp, true);
    if ($fbHttpCode >= 200 && $fbHttpCode < 300 && !empty($fbDecoded['id'])) {
        @file_put_contents($fbMarkerFile, json_encode(array(
            'date' => $fbToday, 'slug' => $newArticleObj['slug'], 'postId' => $fbDecoded['id'],
        ), JSON_UNESCAPED_UNICODE));
    }
}

// ==========================================
// 7a1b. PING BING/YANDEX VIA INDEXNOW
// ==========================================
// One free HTTP call, no account or daily cap to worry about (unlike Facebook/Pinterest
// this carries no lockout risk — IndexNow has no rate-limit-driven ban history on this
// site), so it just fires on every new article with no throttle needed.
if (!empty($newArticleObj['slug'])) {
    require_once __DIR__ . '/indexnow-lib.php';
    @sg_indexnow_submit(array('https://smartgarden.gr/article/' . rawurlencode($newArticleObj['slug'])));
}

// ==========================================
// 7a2. AUTO-PIN THE ARTICLE TO PINTEREST
// ==========================================
// Pins the freshly published article to the board matching its category. The image is
// generated on the fly by pinterest-pin-image.php (1000x1500 branded vertical, the
// static-image format Pinterest uses since Idea Pins were retired in 2024) — Pinterest
// fetches that URL itself, so nothing needs pre-rendering or storing.
//
// Board IDs come from pinterest_boards.json, written by pinterest-create-boards.php.
//
// Standard access was granted on 2026-09-15, so this now pins for real; before that it
// failed every run with API error code 29 ("Apps with Trial access may not create Pins in
// production"). Verified with a live pin the same day: HTTP 201, is_standard true.
// Still deliberately best-effort and silent — a Pinterest outage must never fail an
// article publish.
$pinterestTokensPath = __DIR__ . '/pinterest_tokens.json';
$pinterestBoardsPath = __DIR__ . '/pinterest_boards.json';
if (file_exists($pinterestTokensPath) && file_exists($pinterestBoardsPath)) {
    // The token lasts 30 days and nothing used to renew it, so this was going to stop
    // working one day in October and say nothing.
    require_once __DIR__ . '/pinterest-lib.php';
    list($pinToken, $pinTokenNote) = sg_pinterest_token(__DIR__);
    $pinBoards = json_decode(@file_get_contents($pinterestBoardsPath), true);
    $pinCategory = isset($newArticleObj['category']) ? $newArticleObj['category'] : '';
    $pinBoardId = ($pinCategory && isset($pinBoards[$pinCategory])) ? $pinBoards[$pinCategory] : '';

    if ($pinToken && $pinBoardId) {
        $pinTitle = isset($newArticleObj['title']['el']) ? $newArticleObj['title']['el'] : '';
        $pinSummary = isset($newArticleObj['summary']['el']) ? $newArticleObj['summary']['el'] : '';
        // Pinterest 2026 guidance: keywords in the description text outrank hashtags,
        // so this is a plain keyword-rich sentence set, not a hashtag block.
        $pinDescription = trim($pinSummary) . ' Πλήρης οδηγός βήμα-βήμα για το ελληνικό κλίμα στο SmartGarden.gr.';

        $pinCh = curl_init('https://api.pinterest.com/v5/pins');
        curl_setopt_array($pinCh, array(
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_POST => true,
            CURLOPT_TIMEOUT => 25,
            CURLOPT_HTTPHEADER => array(
                'Authorization: Bearer ' . $pinToken,
                'Content-Type: application/json',
            ),
            CURLOPT_POSTFIELDS => json_encode(array(
                'board_id' => $pinBoardId,
                'title' => mb_substr($pinTitle, 0, 100),
                'description' => mb_substr($pinDescription, 0, 500),
                'link' => 'https://smartgarden.gr/article/' . rawurlencode($newArticleObj['slug']),
                'media_source' => array(
                    'source_type' => 'image_url',
                    'url' => 'https://smartgarden.gr/pinterest-pin-image.php?articleId=' . rawurlencode($newArticleObj['id']),
                ),
            ), JSON_UNESCAPED_UNICODE),
        ));
        // Still best-effort — a Pinterest failure must never fail article publishing — but
        // the answer is recorded now instead of discarded, so a channel that quietly stops
        // working is visible in the log and in the alert email.
        $pinRaw = curl_exec($pinCh);
        $pinStatus = curl_getinfo($pinCh, CURLINFO_HTTP_CODE);
        curl_close($pinCh);
        $pinData = json_decode((string) $pinRaw, true);
        $pinOk = ($pinStatus >= 200 && $pinStatus < 300);

        sg_pinterest_log(array(
            'slug' => $newArticleObj['slug'] ?? '',
            'board' => $pinCategory,
            'http' => $pinStatus,
            'pinId' => $pinData['id'] ?? null,
            'token' => $pinTokenNote,
            'error' => $pinOk ? null : mb_substr((string) ($pinData['message'] ?? $pinRaw), 0, 200, 'UTF-8'),
        ), __DIR__);

        if (!$pinOk) {
            require_once __DIR__ . '/notify.php';
            sg_notify_failure('Pinterest: το αυτόματο pin απέτυχε', array(
                'Άρθρο: ' . ($newArticleObj['slug'] ?? ''),
                'HTTP: ' . $pinStatus,
                'Μήνυμα: ' . mb_substr((string) ($pinData['message'] ?? $pinRaw), 0, 300, 'UTF-8'),
                'Κατάσταση token: ' . $pinTokenNote,
                'Αν χρειάζεται νέα σύνδεση: https://smartgarden.gr/pinterest-auth-login.php',
            ));
        }
    } else {
        require_once __DIR__ . '/pinterest-lib.php';
        sg_pinterest_log(array(
            'slug' => $newArticleObj['slug'] ?? '',
            'board' => $pinCategory,
            'http' => 0,
            'error' => $pinToken ? ('Δεν βρέθηκε board για την κατηγορία ' . $pinCategory) : 'Χωρίς token',
            'token' => $pinTokenNote ?? '',
        ), __DIR__);
    }
}

// ==========================================
// 7a3. QUEUE THE VERTICAL VIDEO (YouTube Short + TikTok)
// ==========================================
// Until now a person had to open TikTok Studio in a browser and sit through a real-time
// canvas recording to get a video out of an article. video-render.php builds the same
// thing server-side: it returns as soon as the job is spawned, and a detached worker does
// the render (~1-2 min) and then uploads to YouTube and TikTok on its own.
//
// &publish=1 is what authorises those uploads. YouTube uploads stay private until someone
// watches them, and TikTok lands in the creator inbox as a draft — neither posts publicly
// without a human, which is the same safety rule as before.
//
// Best-effort and deliberately silent, like the Pinterest and Facebook steps: a video
// problem must never fail article publishing.
$videoJobId = null;
// Defined outside the branch: the previous-day check further down builds a link with it and
// would otherwise depend on this block having run.
$videoKey = $providedKey !== '' ? $providedKey : $VALID_KEYS[0];
if (!empty($newArticleObj['id'])) {
    $videoCh = curl_init('https://smartgarden.gr/video-render.php?action=start&publish=1'
        . '&articleId=' . rawurlencode($newArticleObj['id'])
        . '&key=' . rawurlencode($videoKey));
    curl_setopt_array($videoCh, array(
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 45,
    ));
    $videoResp = json_decode((string) curl_exec($videoCh), true);
    curl_close($videoCh);
    if (!empty($videoResp['job'])) $videoJobId = $videoResp['job'];
}

// ==========================================
// 7b. AUTO-UPDATE SITEMAP.XML WITH ALL ARTICLES
// ==========================================
$sitemapPath = __DIR__ . '/sitemap.xml';
$sitemapXml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n";
$sitemapXml .= "<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n";
$sitemapXml .= "  <url>\n    <loc>https://smartgarden.gr/</loc>\n    <lastmod>" . date('Y-m-d') . "</lastmod>\n    <changefreq>daily</changefreq>\n    <priority>1.0</priority>\n  </url>\n";

// These three .html files have never existed — they answer 200 only because the SPA
// catch-all swallows every unknown path, so the sitemap was handing Google three URLs
// that render the homepage. The real pages built on 2026-09-15 are /privacy and /terms;
// the author page has always been /syntaktis and is already listed below.
$staticPages = array('privacy', 'terms');
foreach ($staticPages as $page) {
    $sitemapXml .= "  <url>\n    <loc>https://smartgarden.gr/" . $page . "</loc>\n    <lastmod>" . date('Y-m-d') . "</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.3</priority>\n  </url>\n";
}

// Client-rendered hub pages (category listings, author bio, planting calendar) — no
// server-side route/file, but real crawlable URLs the SPA handles via pathname routing.
$appRoutes = array('syntaktis', 'imerologio-sporas', 'klima-kipoy', 'pagetos', 'fyta', 'selini', 'xoma');

// /rotiste is a form and a promise until a reader's question has actually been answered on
// it — it says so itself: "Δεν έχει δημοσιευτεί ακόμη καμία ερώτηση". Asking Google to
// index an empty page invites exactly the "thin content" judgement the rest of this work
// exists to avoid, so it joins the sitemap on the day it has something to show.
$qaAnswered = json_decode((string) @file_get_contents(__DIR__ . '/qa_questions.json'), true);
if (is_array($qaAnswered)) {
    $published = array_filter($qaAnswered, function ($q) {
        return !empty($q['answer']) && ($q['status'] ?? 'published') !== 'pending';
    });
    if (count($published) > 0) $appRoutes[] = 'rotiste';
}
foreach ($appRoutes as $route) {
    $sitemapXml .= "  <url>\n    <loc>https://smartgarden.gr/" . $route . "</loc>\n    <lastmod>" . date('Y-m-d') . "</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.6</priority>\n  </url>\n";
}

// One URL per plant in the reference database. Each carries genuinely distinct data
// (cold tolerance, pH, sowing months, its own failure mode), not template substitutions.
$plantsRaw = @file_get_contents(__DIR__ . '/plants.json');
$plantsList = $plantsRaw ? json_decode($plantsRaw, true) : array();
if (is_array($plantsList)) {
    foreach ($plantsList as $plant) {
        if (!isset($plant['slug'])) continue;
        $sitemapXml .= "  <url>\n    <loc>https://smartgarden.gr/fyta/" . rawurlencode($plant['slug']) . "</loc>\n    <lastmod>" . date('Y-m-d') . "</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.5</priority>\n  </url>\n";
    }
}
$categoriesSeen = array();
foreach ($existingArticles as $art) {
    if (isset($art['category']) && !in_array($art['category'], $categoriesSeen)) {
        $categoriesSeen[] = $art['category'];
        $sitemapXml .= "  <url>\n    <loc>https://smartgarden.gr/kategoria/" . rawurlencode($art['category']) . "</loc>\n    <lastmod>" . date('Y-m-d') . "</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.7</priority>\n  </url>\n";
    }
}

// Sitemap <loc> must contain a fully percent-encoded URL (per the sitemaps.org spec) —
// a raw non-ASCII slug like "καλλιέργεια-μαρουλιού" 400s when Googlebot requests it
// literally, which Search Console then reports as a not-found/unindexable URL.
function sitemapSlugToUrl($slug) {
    // Encode each path segment separately so a literal "/" in an id (e.g. "article/x") isn't escaped.
    return implode('/', array_map('rawurlencode', explode('/', $slug)));
}

// Normalize whatever date format an article happens to carry (ISO, "d/m/Y", or a
// Greek "20 Αυγούστου 2026" string) into the "YYYY-MM-DD" the sitemap spec requires.
function sitemapNormalizeDate($raw) {
    if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $raw)) {
        return $raw;
    }
    if (preg_match('#^(\d{1,2})/(\d{1,2})/(\d{4})$#', $raw, $m)) {
        return sprintf('%04d-%02d-%02d', $m[3], $m[2], $m[1]);
    }
    $greekMonths = array(
        'Ιανουαρίου' => 1, 'Φεβρουαρίου' => 2, 'Μαρτίου' => 3, 'Απριλίου' => 4,
        'Μαΐου' => 5, 'Ιουνίου' => 6, 'Ιουλίου' => 7, 'Αυγούστου' => 8,
        'Σεπτεμβρίου' => 9, 'Οκτωβρίου' => 10, 'Νοεμβρίου' => 11, 'Δεκεμβρίου' => 12,
    );
    if (preg_match('/^(\d{1,2})\s+(\S+)\s+(\d{4})$/u', trim($raw), $m) && isset($greekMonths[$m[2]])) {
        return sprintf('%04d-%02d-%02d', $m[3], $greekMonths[$m[2]], $m[1]);
    }
    $ts = strtotime($raw);
    return $ts !== false ? date('Y-m-d', $ts) : date('Y-m-d');
}

foreach ($existingArticles as $art) {
    $artSlug = isset($art['slug']) ? $art['slug'] : (isset($art['id']) ? $art['id'] : '');
    if ($artSlug) {
        $artDate = sitemapNormalizeDate(isset($art['date']) ? $art['date'] : date('Y-m-d'));
        $sitemapXml .= "  <url>\n    <loc>https://smartgarden.gr/article/" . htmlspecialchars(sitemapSlugToUrl($artSlug)) . "</loc>\n    <lastmod>" . $artDate . "</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.9</priority>\n  </url>\n";
    }
}
$sitemapXml .= "</urlset>\n";
@file_put_contents($sitemapPath, $sitemapXml);

// ==========================================
// 7c. AUTO-UPDATE RSS.XML WITH THE LATEST ARTICLES
// (was previously a stale, hand-written file with broken /article/published-<id>
// links and "Invalid Date" pubDates — now regenerated from the real article list,
// same slugs the site itself links to.)
// ==========================================
$rssPath = __DIR__ . '/rss.xml';
$rssItems = array_slice($existingArticles, 0, 30);
$rssXml = "<?xml version=\"1.0\" encoding=\"UTF-8\" ?>\n";
$rssXml .= "<rss version=\"2.0\" xmlns:atom=\"http://www.w3.org/2005/Atom\">\n<channel>\n";
$rssXml .= "  <title>SmartGarden.gr - Επιστημονική Γεωπονία &amp; Αστική Κηπουρική</title>\n";
$rssXml .= "  <link>https://smartgarden.gr</link>\n";
$rssXml .= "  <description>Εξειδικευμένοι τεχνικοί οδηγοί, βιολογική φυτοπροστασία, αυτοματισμοί ποτίσματος και αστική κηπουρική.</description>\n";
$rssXml .= "  <language>el</language>\n";
$rssXml .= "  <lastBuildDate>" . gmdate('D, d M Y H:i:s') . " GMT</lastBuildDate>\n";
$rssXml .= "  <atom:link href=\"https://smartgarden.gr/rss.xml\" rel=\"self\" type=\"application/rss+xml\" />\n";

foreach ($rssItems as $art) {
    $artSlug = isset($art['slug']) ? $art['slug'] : (isset($art['id']) ? $art['id'] : '');
    if (!$artSlug) continue;
    $artTitle = is_array($art['title']) ? ($art['title']['el'] ?? '') : ($art['title'] ?? '');
    $artSummary = is_array($art['summary']) ? ($art['summary']['el'] ?? '') : ($art['summary'] ?? '');
    $artCategory = is_array($art['categoryLabel']) ? ($art['categoryLabel']['el'] ?? '') : ($art['category'] ?? '');
    $artDateRaw = isset($art['date']) ? $art['date'] : date('Y-m-d');
    $ts = strtotime($artDateRaw);
    $pubDate = ($ts !== false) ? gmdate('D, d M Y H:i:s', $ts) . ' GMT' : gmdate('D, d M Y H:i:s') . ' GMT';
    $artUrl = 'https://smartgarden.gr/article/' . htmlspecialchars($artSlug);

    $rssXml .= "  <item>\n";
    $rssXml .= "    <title>" . htmlspecialchars($artTitle) . "</title>\n";
    $rssXml .= "    <link>" . $artUrl . "</link>\n";
    $rssXml .= "    <guid>" . $artUrl . "</guid>\n";
    $rssXml .= "    <pubDate>" . $pubDate . "</pubDate>\n";
    $rssXml .= "    <description>" . htmlspecialchars($artSummary) . "</description>\n";
    $rssXml .= "    <category>" . htmlspecialchars($artCategory) . "</category>\n";
    $rssXml .= "  </item>\n";
}
$rssXml .= "</channel>\n</rss>\n";
@file_put_contents($rssPath, $rssXml);

// ==========================================
// 7c. AUTO-NOTIFY GOOGLE INDEXING API (INSTANT CRAWL)
// ==========================================
// $articleSlug was never assigned anywhere in this file, so this URL had been coming out
// as the bare .../article/ with no slug. It isn't only cosmetic: this same variable is
// what gets submitted to the Google Indexing API below, so every daily run was asking
// Google to re-crawl the listing URL instead of the article just published.
$newPublishedUrl = 'https://smartgarden.gr/article/' . rawurlencode($newArticleObj['slug']);
$googleIndexed = false;

// Was hand-rolled here and carried two faults that made it a no-op for its entire life:
// it looked for a filename the server has never had, and built the JWT with base64_encode
// where the spec requires base64url — so even with the key found, Google would have
// rejected every signature. Both live in indexing-lib.php now, used by this and by
// request-indexing.php, so there is one implementation to be wrong instead of two.
require_once __DIR__ . '/indexing-lib.php';
list($idxToken, $idxErr) = sg_indexing_token();
if ($idxToken) {
    $idxResult = sg_submit_url($idxToken, $newPublishedUrl);
    $googleIndexed = $idxResult['ok'];
}

// ==========================================
// 8. OUTPUT JSON RESPONSE
// ==========================================
echo json_encode(array(
    'status' => 'success',
    'message' => 'New scientific agronomy article published successfully.',
    'execution_time' => date('Y-m-d H:i:s'),
    'topic_slug' => $selectedTopic['slug'],
    'title' => $selectedTopic['title'],
    'category' => $selectedTopic['category'],
    'read_time' => $selectedTopic['readTime'],
    'word_count' => $generatedWordCount,
    'wordpress_synced' => $wpLoaded,
    'wordpress_post_id' => $wpPostId,
    'google_indexed' => $googleIndexed,
    'published_url' => $newPublishedUrl,
    'video_job' => $videoJobId,
    'total_stored_articles' => count($existingArticles)
), JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
